#!/bin/bash
# Solution for T1_wamm -> HashCollisionGame.
#
# WaMM keeps an 8192-bit internal state (32x32 byte matrix). Each 256-bit message
# vector is XORed into one state row; after every full 8192-bit block the state is
# squared. Since an entire block is XORed before any mixing, a chosen second block
# forces two distinct messages to the same internal state (Wilson, 2008):
#   m  = m0  || m1 ,  m' = m0' || m1'  with  m1' = m1 XOR S XOR S'
#   S  = state after block m0 , S' = state after block m0'.
# Equal lengths then give identical digests for any output length.
#
# The colliding pair below was crafted offline with a faithful WaMM state model
# (m0 = 0x11*1024, m0' = 0x22*1024, m1 = 0x33*1024) and verified against the
# reference CLI for 256- and 512-bit digests. Both messages are 2048 bytes.

cat > /app/attack.py <<'ATTACK_PY_EOF'
import json
import subprocess
import sys

SERVER_URL = "http://game_controller:8000"

# Precomputed WaMM state-overwrite colliding pair (2048 bytes each, distinct).
plaintext1 = ""
plaintext2 = ""

assert plaintext1 != plaintext2, "messages must differ"


# (Optional) confirm the collision via the hash oracle before submitting.
def hash_oracle(pt):
    r = subprocess.run(
        ["curl", "-s", "-X", "POST", f"{SERVER_URL}/oracle_query",
         "-H", "Content-Type: application/json",
         "-d", json.dumps({"oracle_type": "hash",
                           "arguments": {"plaintext": pt}})],
        capture_output=True, text=True,
    )
    try:
        return json.loads(r.stdout).get("oracle_result", {}).get("hash")
    except Exception:
        return None


h1, h2 = hash_oracle(plaintext1), hash_oracle(plaintext2)
print(f"hash(plaintext1) = {h1}")
print(f"hash(plaintext2) = {h2}")
if h1 is not None and h2 is not None:
    print(f"oracle collision check: {'MATCH' if h1 == h2 else 'MISMATCH'}")

# Submit the collision.
print("Submitting collision to HashCollisionGame...")
r = subprocess.run(
    ["curl", "-s", "-X", "POST", f"{SERVER_URL}/execute_current_stage",
     "-H", "Content-Type: application/json",
     "-d", json.dumps({"stage_payload": {"plaintext1": plaintext1,
                                         "plaintext2": plaintext2}})],
    capture_output=True, text=True,
)
print(f"Game response: {r.stdout.strip()}")
resp = json.loads(r.stdout)
if resp.get("stage_result", {}).get("Game won") == "Yes":
    print("SUCCESS: WaMM hash collision accepted.")
else:
    print("FAILURE: collision not accepted.")
    sys.exit(1)
ATTACK_PY_EOF

cat > /app/attack.sh <<'ATTACK_SH_EOF'
#!/bin/bash
python3 /app/attack.py
ATTACK_SH_EOF
chmod +x /app/attack.sh

echo "HashCollisionGame" > /app/security_game_choice.txt

echo "Finished executing all steps in the solve.sh script."
